const QUESTIONS = [{"id": "a1", "section": "A", "title": "Soalan 1", "intro": "Tukarkan 1 3/5 juta kepada nombor bulat.", "fields": [{"id": "a1", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 1600000, "max": 2, "topic": "Nombor bulat dan operasi asas", "model": "1 3/5 juta = 8/5 × 1 000 000 (1) = 1 600 000 (1).", "displayUnit": "nombor bulat"}], "topic": "Nombor bulat dan operasi asas"}, {"id": "a2", "section": "A", "title": "Soalan 2", "intro": "Cari nilai anu dalam ayat matematik: (□ + 1 250 000) ÷ 5 = 700 000.", "fields": [{"id": "a2", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 2250000, "max": 2, "topic": "Nombor bulat dan operasi asas", "model": "700 000 × 5 = 3 500 000 (1). Anu = 3 500 000 − 1 250 000 = 2 250 000 (1).", "displayUnit": "nombor bulat"}], "topic": "Nombor bulat dan operasi asas"}, {"id": "a3", "section": "A", "title": "Soalan 3", "intro": "Hitung 3 1/2 ÷ 2/3. Berikan jawapan dalam pecahan atau perpuluhan.", "fields": [{"id": "a3", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 5.25, "max": 2, "topic": "Pecahan, perpuluhan dan peratus", "model": "3 1/2 ÷ 2/3 = 7/2 × 3/2 (1) = 21/4 = 5 1/4 atau 5.25 (1)."}], "topic": "Pecahan, perpuluhan dan peratus"}, {"id": "a4", "section": "A", "title": "Soalan 4", "intro": "Hitung 2.4 × 1.35.", "fields": [{"id": "a4", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 3.24, "max": 2, "topic": "Pecahan, perpuluhan dan peratus", "model": "24 × 135 = 3 240; jumlah tempat perpuluhan ialah tiga (1). Jawapan = 3.240 = 3.24 (1)."}], "topic": "Pecahan, perpuluhan dan peratus"}, {"id": "a5", "section": "A", "title": "Soalan 5", "intro": "Sepasang kasut berharga RM180 sebelum diskaun. Kedai memberikan diskaun 20%. Hitung harga kasut selepas diskaun.", "fields": [{"id": "a5", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 144, "max": 2, "topic": "Wang", "model": "Diskaun = 20/100 × RM180 = RM36 (1). Harga selepas diskaun = RM180 − RM36 = RM144 (1).", "displayUnit": "RM", "units": ["RM", "ringgit"]}], "topic": "Wang"}, {"id": "a6", "section": "A", "title": "Soalan 6", "intro": "Sofia mempunyai pelaburan sebanyak RM2 500. Kadar dividen yang diberi dalam soalan ini ialah 4% bagi satu tahun. Hitung dividen yang diterimanya.", "fields": [{"id": "a6", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 100, "max": 2, "topic": "Wang", "model": "Dividen = 4/100 × RM2 500 (1) = RM100 (1). Kadar ini data rekaan untuk latihan.", "displayUnit": "RM", "units": ["RM", "ringgit"]}], "topic": "Wang"}, {"id": "a7", "section": "A", "title": "Soalan 7", "intro": "Bandar X menggunakan GMT+9 dan Bandar Y menggunakan GMT+5. Waktu di X ialah 16:40. Nyatakan waktu di Y pada hari yang sama dalam format 24 jam.", "fields": [{"id": "a7", "type": "math", "kind": "time", "label": "Jawapan akhir", "answer": "12:40", "max": 2, "topic": "Masa dan waktu", "model": "Perbezaan masa = 9 − 5 = 4 jam (1). Waktu di Y = 16:40 − 4 jam = 12:40 (1).", "displayUnit": "HH:MM (24 jam)"}], "topic": "Masa dan waktu"}, {"id": "a8", "section": "A", "title": "Soalan 8", "intro": "Bandar X menggunakan GMT+8 dan Bandar Z menggunakan GMT+3. Waktu di X ialah 02:20 pada 7 Disember 2026. Nyatakan waktu dan tarikh di Z.", "fields": [{"id": "a8a", "type": "math", "kind": "time", "label": "(a) Waktu di Z dalam format 24 jam.", "answer": "21:20", "max": 1, "topic": "Masa dan waktu", "model": "Z lewat 5 jam. 02:20 − 5 jam = 21:20 pada hari sebelumnya (1).", "displayUnit": "HH:MM (24 jam)"}, {"id": "a8b", "type": "math", "kind": "word", "label": "(b) Tarikh di Z.", "answer": "6 Disember 2026", "max": 1, "topic": "Masa dan waktu", "model": "6 Disember 2026 (1). Terima 06/12/2026 atau 6 Dis 2026.", "accepted": ["6 Disember 2026", "06 Disember 2026", "6 Dis 2026", "06 Dis 2026", "6/12/2026", "06/12/2026", "6-12-2026", "06-12-2026"], "displayUnit": "hh/bb/tttt"}], "topic": "Masa dan waktu"}, {"id": "a9", "section": "A", "title": "Soalan 9", "intro": "Kain seragam sepanjang 2.4 m mempunyai jisim 0.75 kg. Hitung jisim kain yang sama jenis sepanjang 9.6 m.", "fields": [{"id": "a9", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 3, "max": 2, "topic": "Ukuran dan sukatan", "model": "9.6 ÷ 2.4 = 4 (1). Jisim = 4 × 0.75 kg = 3 kg (1).", "displayUnit": "kg", "units": ["kg", "kilogram"]}], "topic": "Ukuran dan sukatan"}, {"id": "a10", "section": "A", "title": "Soalan 10", "intro": "Rajah menunjukkan bulatan berpusat O. Panjang diameter CD ialah 12.8 cm. Berapakah panjang jejari OD?", "fields": [{"id": "a10", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 6.4, "max": 2, "topic": "Ruang", "model": "Jejari = diameter ÷ 2 (1) = 12.8 cm ÷ 2 = 6.4 cm (1).", "displayUnit": "cm", "units": ["cm", "sentimeter"]}], "topic": "Ruang", "image": "assets/math2-circle.svg", "imageAlt": "Bulatan berpusat O. C dan D ialah hujung diameter sepanjang 12.8 cm. OD ialah jejari. Rajah tidak mengikut skala."}, {"id": "a11", "section": "A", "title": "Soalan 11", "intro": "Sebuah oktagon sekata mempunyai jumlah sudut pedalaman 1 080°. Hitung satu sudut pedalamannya.", "fields": [{"id": "a11", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 135, "max": 2, "topic": "Ruang", "model": "Oktagon sekata mempunyai 8 sudut sama besar (1). Satu sudut = 1 080° ÷ 8 = 135° (1).", "displayUnit": "darjah (°)", "units": ["°", "darjah"]}], "topic": "Ruang"}, {"id": "a12", "section": "A", "title": "Soalan 12", "intro": "Pada peta grid, P berada di (4, 1) dan Q di (4, 7). Skala mencancang ialah 1 unit mewakili 3 km. Hitung jarak sebenar antara P dengan Q.", "fields": [{"id": "a12", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 18, "max": 2, "topic": "Koordinat, nisbah dan kadaran", "model": "Beza koordinat mencancang = 7 − 1 = 6 unit (1). Jarak = 6 × 3 km = 18 km (1).", "displayUnit": "km", "units": ["km", "kilometer"]}], "topic": "Koordinat, nisbah dan kadaran", "image": "assets/math2-grid.svg", "imageAlt": "Grid sukuan pertama: P (4,1), Q (4,7). Jarak antara kedua-duanya mencancang; 1 unit mewakili 3 km."}, {"id": "a13", "section": "A", "title": "Soalan 13", "intro": "Carta pai menunjukkan hobi 64 orang murid. Sektor Membaca ialah 180°, Melukis 90°, Catur 45° dan Berkebun 45°. Berapakah bilangan murid yang memilih Catur?", "fields": [{"id": "a13", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 8, "max": 2, "topic": "Pengurusan data dan kebolehjadian", "model": "Bahagian Catur = 45°/360° = 1/8 (1). Bilangan murid = 1/8 × 64 = 8 orang (1).", "displayUnit": "orang", "units": ["orang", "murid"]}], "topic": "Pengurusan data dan kebolehjadian", "image": "assets/math2-pie.svg", "imageAlt": "Carta pai hobi 64 murid: Membaca 180°, Melukis 90°, Catur 45° dan Berkebun 45°. Jumlah sudut 360°."}, {"id": "b1", "section": "B", "title": "1. Projek buku dan pameran", "intro": "Jawab semua bahagian. Setiap situasi adalah berasingan. Tunjukkan jalan kerja di ruang yang disediakan.", "fields": [{"id": "b1a", "type": "math", "kind": "number", "label": "(a) Sebuah penerbit mencetak 2.35 juta buku latihan pada tahun pertama dan 1 1/4 juta pada tahun kedua. Hitung jumlah buku yang dicetak dalam nombor bulat.", "answer": 3600000, "max": 2, "topic": "Nombor bulat dan operasi asas", "model": "1 1/4 juta = 1.25 juta; jumlah = 2.35 + 1.25 = 3.6 juta (1) = 3 600 000 buah buku (1).", "displayUnit": "buah", "units": ["buah", "buku"]}, {"id": "b1b", "type": "math", "kind": "number", "label": "(b) Sebuah pusat pameran menerima 0.6 juta pengunjung tahun lalu. Bilangan pengunjung tahun ini ialah 150% daripada tahun lalu. Hitung bilangan pengunjung tahun ini dalam nombor bulat.", "answer": 900000, "max": 3, "topic": "Pecahan, perpuluhan dan peratus", "model": "150% = 1.5 (1). 1.5 × 0.6 juta = 0.9 juta (1). Bilangan pengunjung = 900 000 orang (1).", "displayUnit": "orang", "units": ["orang", "pengunjung"]}, {"id": "b1c", "type": "math", "kind": "number", "label": "(c) Kos sebuah buku cenderamata ialah RM18. Harga tandanya RM25. Pembeli diberi rebat RM1.50. Hitung untung bagi sebuah buku.", "answer": 5.5, "max": 2, "topic": "Wang", "model": "Harga jual sebenar = RM25 − RM1.50 = RM23.50 (1). Untung = RM23.50 − RM18 = RM5.50 (1).", "displayUnit": "RM", "units": ["RM", "ringgit"]}, {"id": "b1d", "type": "math", "kind": "time", "label": "(d) Penerbangan bertolak dari Bandar A (GMT+2) pada 14:25. Tempoh penerbangan ke Bandar B (GMT+5) ialah 3 jam. Nyatakan waktu tempatan ketibaan di B dalam format 24 jam.", "answer": "20:25", "max": 2, "topic": "Masa dan waktu", "model": "Tiba pada 17:25 mengikut waktu A (1). B awal 3 jam: 17:25 + 3 jam = 20:25 (1).", "displayUnit": "HH:MM (24 jam)"}, {"id": "b1e", "type": "math", "kind": "number", "label": "(e) Nisbah lencana merah kepada lencana biru ialah 3 : 5. Terdapat 320 lencana semuanya. Hitung bilangan lencana biru.", "answer": 200, "max": 3, "topic": "Koordinat, nisbah dan kadaran", "model": "Jumlah bahagian = 3 + 5 = 8 (1). Satu bahagian = 320 ÷ 8 = 40 (1). Lencana biru = 5 × 40 = 200 (1).", "displayUnit": "lencana", "units": ["lencana"]}]}, {"id": "b2", "section": "B", "title": "2. Hari Kelab Sekolah", "intro": "Jawab semua bahagian. Setiap situasi adalah berasingan. Data dan kadar dalam soalan ialah rekaan untuk latihan.", "fields": [{"id": "b2ai", "type": "math", "kind": "number", "label": "(a)(i) Sebanyak 2 L jus mempunyai jisim 1.6 kg. Pada kadar campuran yang sama, hitung jisim 9 L jus.", "answer": 7.2, "max": 2, "topic": "Ukuran dan sukatan", "model": "Faktor gandaan = 9 ÷ 2 = 4.5 (1). Jisim = 4.5 × 1.6 kg = 7.2 kg (1).", "displayUnit": "kg", "units": ["kg", "kilogram"]}, {"id": "b2aii", "type": "math", "kind": "number", "label": "(a)(ii) Semua 9 L jus itu diisi ke dalam botol 375 mL. Berapakah botol penuh yang diperoleh?", "answer": 24, "max": 2, "topic": "Ukuran dan sukatan", "model": "9 L = 9 000 mL (1). Bilangan botol = 9 000 ÷ 375 = 24 botol (1).", "displayUnit": "botol", "units": ["botol"]}, {"id": "b2b", "type": "math", "kind": "number", "label": "(b) Sebuah bulatan hiasan dibahagikan kepada 8 sektor sama besar. Hitung sudut pada pusat bagi satu sektor.", "answer": 45, "max": 2, "topic": "Ruang", "model": "Satu putaran lengkap = 360° (1). Sudut bagi satu sektor = 360° ÷ 8 = 45° (1).", "displayUnit": "darjah (°)", "units": ["°", "darjah"]}, {"id": "b2c", "type": "math", "kind": "number", "label": "(c) Empat buku nota berharga RM18. Pada kadar yang sama, hitung harga 10 buku nota.", "answer": 45, "max": 2, "topic": "Koordinat, nisbah dan kadaran", "model": "Harga satu buku nota = RM18 ÷ 4 = RM4.50 (1). Harga 10 buku nota = 10 × RM4.50 = RM45 (1).", "displayUnit": "RM", "units": ["RM", "ringgit"]}, {"id": "b2di", "type": "math", "kind": "number", "label": "(d)(i) Daripada 96 orang murid, 48 memilih aktiviti kraftangan. Hitung sudut sektor Kraftangan dalam carta pai bagi semua murid.", "answer": 180, "max": 2, "topic": "Pengurusan data dan kebolehjadian", "model": "Bahagian Kraftangan = 48/96 = 1/2 (1). Sudut sektor = 1/2 × 360° = 180° (1).", "displayUnit": "darjah (°)", "units": ["°", "darjah"]}, {"id": "b2dii", "type": "math", "kind": "word", "label": "(d)(ii) Sebuah beg hanya mengandungi 6 bola kuning. Sebiji bola diambil tanpa melihat. Nyatakan kebolehjadian mendapat bola kuning menggunakan istilah yang sesuai.", "answer": "Pasti", "max": 1, "topic": "Pengurusan data dan kebolehjadian", "model": "Pasti (1), kerana semua bola di dalam beg berwarna kuning.", "accepted": ["pasti"]}, {"id": "b2diii", "type": "text", "label": "(d)(iii) Berikan sebab bagi jawapan (d)(ii).", "max": 1, "topic": "Pengurusan data dan kebolehjadian", "model": "Semua bola di dalam beg berwarna kuning / beg hanya mengandungi bola kuning / tiada bola warna lain (1). Terima alasan setara yang betul.", "reasonAlternatives": [[["semua", "hanya", "kesemua"], ["kuning"]], [["tiada", "tidak ada"], ["warna lain"]]]}]}];
